 public static async Task<object> Screens(){Guard();var rows=new List<object>();var player=PlayerController.Instance;var origin=player.Position;bool inv=Tuning.Invincible;Tuning.Invincible=true;Application.runInBackground=true;try{using(var input=new InputScope()){player.Teleport(new Vector2(-6,16));Camera.main.GetComponent<DungeonCamera>().Snap();await Task.Delay(1000);foreach(int h in new[]{720,1080})using(var size=new SizeScope(h==720?1280:1920,h)){await Task.Delay(900);input.Pointer=null;await Capture("hud",h);for(int i=0;i<3;i++){await Click(input,DungeonHud.UtilityRect(i));string expected=new[]{Inventory.BagWindow,BigMap.MapModal,SkillPanel.ModalName}[i];bool clickOpened=DungeonUi.Modal==expected;rows.Add(new{height=h,utility=i,clickOpened,modal=DungeonUi.Modal});if(!clickOpened)await KeyTap(input,new[]{Key.I,Key.M,Key.K}[i]);await Capture(expected,h);await KeyTap(input,Key.Escape);input.Pointer=null;}await KeyTap(input,Key.F1);var log=ExplorationLog.Instance;typeof(ExplorationLog).GetField("_scroll",F).SetValue(log,Vector2.zero);await Task.Delay(250);await Capture("f1-top",h);if(!log.PanelVisible)throw new Exception("F1 panel inaccessible");typeof(ExplorationLog).GetField("_scroll",F).SetValue(log,new Vector2(0,1300));await Task.Delay(350);await Capture("f1-middle",h);typeof(ExplorationLog).GetField("_scroll",F).SetValue(log,new Vector2(0,9000));await Task.Delay(350);await Capture("f1-bottom",h);rows.Add(new{height=h,f1=true,scroll=typeof(ExplorationLog).GetField("_scroll",F).GetValue(log).ToString()});await KeyTap(input,Key.F1);}}}finally{Tuning.Invincible=inv;player.Teleport(origin);Camera.main.GetComponent<DungeonCamera>().Snap();}File.WriteAllText(Root+"/ui/screens-checks.json",Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));return rows;}
 public static async Task<object> Actions(){Guard();Application.runInBackground=true;var p=PlayerController.Instance;var origin=p.Position;bool inv=Tuning.Invincible;Tuning.Invincible=true;var rows=new List<object>();try{using(var input=new InputScope())using(var size=new SizeScope(1920,1080)){p.Teleport(new Vector2(-6,16));Camera.main.GetComponent<DungeonCamera>().Snap();await Task.Delay(800);for(int i=0;i<5;i++){input.Pointer=null;await Task.Delay(500);if(i==4)p.Health.SetCurrent(p.Health.Max-400);int potions=p.Potions,hp=p.Health.Current;await Click(input,DungeonHud.ActionRect(i));bool okay=i==0?p.Pose==PlayerPose.Attack:i==1?p.WhirlCooldown>0:i==2?p.WaveCooldown>0:i==3?p.DodgeCooldown>0:p.Potions==potions-1&&p.Health.Current>hp;rows.Add(new{action=i,okay,pose=p.Pose.ToString(),facing=p.FacingDirection.ToString(),whirl=p.WhirlCooldown,wave=p.WaveCooldown,dodge=p.DodgeCooldown,potions=p.Potions,hp=p.Health.Current});await Capture("action-"+i,1080);await Task.Delay(700);}input.Pointer=null;var from=p.Position;input.Keys=new[]{Key.W};await Task.Delay(700);input.Keys=Array.Empty<Key>();await Task.Delay(150);rows.Add(new{movement=(p.Position-from).magnitude,okay=(p.Position-from).magnitude>.3f});var progress=PlayerProgress.Instance;int oldXp=progress.TotalXp;await Capture("xp-before",1080);progress.GrantXp(100);await Task.Delay(500);await Capture("xp-after",1080);rows.Add(new{xpBefore=oldXp,xpAfter=progress.TotalXp,fraction=progress.XpFraction,okay=progress.TotalXp==oldXp+100});progress.GrantXp(progress.XpToNext-progress.Xp+40);await Task.Delay(500);await Capture("xp-level-up",1080);rows.Add(new{level=progress.Level,xp=progress.Xp,points=progress.SkillPoints,okay=progress.Level>=2&&progress.Xp==40});}}finally{Tuning.Invincible=inv;p.Teleport(origin);Camera.main.GetComponent<DungeonCamera>().Snap();}File.WriteAllText(Root+"/ui/actions-checks.json",Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));return rows;}
 public static object Visibility(){Guard();var root=DungeonRoot.Instance;var states=root.World.Cells.Select(c=>(cell:c,visited:c.Visited)).ToArray();var edge=root.World.Edges.FirstOrDefault(e=>e.Kind==Demo6.Core.Dungeon.EdgeKind.Plank);if(edge==null)throw new Exception("No actual secret wall to test");bool old=edge.Opened;bool reveal=BigMap.Instance.RevealAll;try{foreach(var v in states)v.cell.Visited=false;edge.A.Visited=true;edge.Opened=false;BigMap.Instance.RevealAll=true;bool closed=!DungeonMiniMap.ShowsCell(edge.B)&&!BigMap.RouteKnown(edge);edge.Opened=true;bool opened=DungeonMiniMap.ShowsCell(edge.B)&&BigMap.RouteKnown(edge);var result=new{closedSecretHidden=closed,openedExitVisible=opened,debugRevealDoesNotLeak=closed,enemyMarkerSource=false};Directory.CreateDirectory(Root+"/ui");File.WriteAllText(Root+"/ui/visibility-checks.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));if(!closed||!opened)throw new Exception("Minimap exploration gate failed");return result;}finally{foreach(var v in states)v.cell.Visited=v.visited;edge.Opened=old;BigMap.Instance.RevealAll=reveal;}}

 public static async Task<object> Flows(){Guard();var rows=new List<object>();bool inv=Tuning.Invincible;Tuning.Invincible=true;try{using(var input=new InputScope()){foreach(int h in new[]{720,1080})using(var size=new SizeScope(h==720?1280:1920,h)){await Task.Delay(700);if(DungeonUi.Modal!=null)DungeonUi.Close(DungeonUi.Modal);await Click(input,DungeonMiniMap.PanelRect);rows.Add(new{height=h,minimapClick=DungeonUi.Modal==BigMap.MapModal});await KeyTap(input,Key.Escape);await Click(input,DungeonHud.UtilityRect(0));var r=new Rect((DungeonUi.Width-1200)*.5f,(DungeonUi.Height-760)*.5f,1200,760);var inventory=Inventory.Instance;var slot=(Demo6.Core.Loot.GearSlot)2;var item=inventory.Equipment[slot];await Click(input,new Rect(r.x+300,r.y+100,72,72));bool selected=ReferenceEquals(typeof(Inventory).GetField("_selected",F).GetValue(inventory),item);await Click(input,new Rect(r.x+894,r.y+592,290,48));bool starterKept=ReferenceEquals(inventory.Equipment[slot],item);var bag=(List<Demo6.Core.Loot.GearItem>)typeof(Inventory).GetField("_bag",F).GetValue(inventory);var fixture=new Demo6.Core.Loot.GearItem(item.BaseId,item.Grade,2,1000);bag.Insert(0,fixture);await Task.Delay(100);await Click(input,new Rect(r.x+57,r.y+330,80,80));await Click(input,new Rect(r.x+894,r.y+592,290,48));bool equippedFixture=ReferenceEquals(inventory.Equipment[slot],fixture);int originalIndex=bag.IndexOf(item);if(originalIndex<0)throw new Exception("Equipped item not returned to bag");await Click(input,new Rect(r.x+57+(originalIndex%5)*90,r.y+330+(originalIndex/5)*90,80,80));await Click(input,new Rect(r.x+894,r.y+592,290,48));bool restored=ReferenceEquals(inventory.Equipment[slot],item);bag.Remove(fixture);rows.Add(new{height=h,selected,starterKept,equippedFixture,restored});await Capture("bag-flow",h);await Click(input,DungeonUi.CloseButtonRect(r));rows.Add(new{height=h,bagClose= !DungeonUi.ModalOpen});await Click(input,DungeonHud.UtilityRect(2));var skillRect=new Rect((DungeonUi.Width-950)*.5f,(DungeonUi.Height-570)*.5f,950,570);var progress=PlayerProgress.Instance;var panel=UnityEngine.Object.FindAnyObjectByType<SkillPanel>();int rank=progress.Rank(panel.SelectedSkill);if(h==720){if(progress.SkillPoints<1)progress.GrantXp(progress.XpToNext-progress.Xp);int points=progress.SkillPoints;await Click(input,new Rect(skillRect.x+398,skillRect.y+480,500,48));rows.Add(new{height=h,skillRank=progress.Rank(panel.SelectedSkill)==rank+1,skillPointSpent=progress.SkillPoints==points-1});}await Click(input,DungeonUi.CloseButtonRect(skillRect));rows.Add(new{height=h,skillClose=!DungeonUi.ModalOpen});await KeyTap(input,Key.F1);var log=ExplorationLog.Instance;typeof(ExplorationLog).GetField("_scroll",F).SetValue(log,Vector2.zero);await Task.Delay(300);await Capture("f1-real-top",h);bool originalInv=Tuning.Invincible;await Click(input,new Rect(DungeonUi.Width-310,748,75,22));bool toggleChanged=Tuning.Invincible!=originalInv;await Click(input,new Rect(DungeonUi.Width-310,748,75,22));rows.Add(new{height=h,f1InvincibleToggle=toggleChanged,f1ToggleRestored=Tuning.Invincible==originalInv});await KeyTap(input,Key.M);await Capture("map-with-f1",h);await KeyTap(input,Key.Escape);var f1Rect=new Rect(DungeonUi.Width-432,12,420,DungeonUi.Height-24);await Click(input,DungeonUi.CloseButtonRect(f1Rect));rows.Add(new{height=h,f1Close=!log.PanelVisible});}}}finally{Tuning.Invincible=inv;}File.WriteAllText(Root+"/ui/flows-checks.json",Newtonsoft.Json.JsonConvert.SerializeObject(rows,Newtonsoft.Json.Formatting.Indented));return rows;}

